ST.xhtml:
// Для линеаризации характеристики датчика используем два поддиапазона
// В нижнем диапазоне (примерно 20% от номинала) аппроксимируем полиномом 2-го порядка: Y = A x^2 + B x + C
// верхние 80% аппроксимируем линейной функцией: Y = A x + B
// Коэффициенты рассчитываются в полуавтоматическом режиме ПО АРМ и загружаются в ПЛК при калибровке датчика
// Коэффициенты расчитываются для положительных значений датчика момента. Для отрицательных значений датчика у коэффициентов
// при четных степенях нужно поменять знак.
// Пример: для X > 0: Y = A x^2 + B x + C; Y = A x + B
//         для X < 0: Y = -A x^2 + B x - C, Y = A x - B
IF rTorque >= 0 THEN
	torque_sign := 1;
ELSE
	torque_sign := -1;
END_IF

lo := torque_sign * GVL.rA1 * EXPT(rTorque, 2) + GVL.rB1 * rTorque + torque_sign * GVL.rC1;
hi := GVL.rA2 * rTorque + torque_sign * GVL.rB2;

torque_abs := ABS(GVL.rTorque);
k1 := (torque_abs - 10.0)/5.0;
k2 := (1 - k1);

IF ABS(GVL.rTorque) < 10 THEN
	GetCalibratedTorque := lo;
ELSIF GVL.rTorque > 15 THEN
	GetCalibratedTorque := hi;
ELSE
	GetCalibratedTorque := k2 * lo + k1 * hi;
END_IF
